7	\begin{enumerate}
8	    \item 假设某路径可能存在越界/溢出/未检查条件；
9	    \item 生成可执行输入或触发脚本；
10	    \item 在 sanitizer/debugger 下运行并收集证据；
11	    \item 失败则修正假设并继续探索，直到复现或证伪。
12	\end{enumerate}
13	\end{knowledgebox}
